            }
            fn visit_string<E>(self, s: String) -> Result<Self::Value, E> where E: serde::de::Error {
                Ok(s)
            }
            // For any other type, return error
            fn visit_bool<E>(self, v: bool) -> Result<Self::Value, E> where E: serde::de::Error {
                Err(serde::de::Error::invalid_type(serde::de::Unexpected::Bool(v), &self))
            }
            fn visit_i64<E>(self, v: i64) -> Result<Self::Value, E> where E: serde::de::Error {
                Err(serde::de::Error::invalid_type(serde::de::Unexpected::Signed(v), &self))
