// For complex filter/sorter etc, using String is simplification, but may still produce correct errors for simple cases.
// Ideally we should have precise types, but using String will cause some variants to accept any string, which may not match original's complex validation.
// However, for our simplified implementation, let's keep String for complex ones and handle.

fn format_template(template: &str, args: &[String]) -> Result<String, String> {
    // Returns formatted YAML string or error message (without prefix)
    let mut result = String::new();
    let mut arg_idx = 0;
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '%' {
            if i + 1 >= chars.len() {
                return Err(format!("error: xplr -m: template ended with incomplete placeholder\n"));
            }
            let next = chars[i + 1];
            match next {
                '%' => {
                    result.push('%');
                    i += 2;
                }
                's' => {
                    if arg_idx >= args.len() {
                        // column is 1-indexed position of % in original template
                        // Compute column by char count up to i (but need byte column? Original counts bytes? We have char count as bytes for ascii)
                        let col = template[..i].chars().count() + 1;
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col));
                    }
                    result.push_str(&args[arg_idx]);
                    arg_idx += 1;
                    i += 2;
                }
                'q' => {
                    if arg_idx >= args.len() {
                        let col = template[..i].chars().count() + 1;
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col));
                    }
                    // quoted: use json string
                    let quoted = serde_json::to_string(&args[arg_idx]).unwrap_or_else(|_| "\"\"".to_string());
                    result.push_str(&quoted);
                    arg_idx += 1;
                    i += 2;
                }
                _ => {
                    let col = template[..i].chars().count() + 1;
                    // The placeholder is e.g., "% " or "%x" - we need to include the two chars
                    let ph = format!("%{}", next);
                    return Err(format!("error: xplr -m: invalid placeholder '{}' at column {}, use one of '%s' or '%q', or escape it using '%%'\n", ph, col));
                }
            }
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }
    if arg_idx < args.len() {
        return Err(format!("error: xplr -m: too many positional values, not enough positional placeholders\n"));
    }
    Ok(result)
}

fn parse_message(yaml_str: &str) -> Result<String, String> {
    // yaml_str is formatted YAML (or JSON) template result.
    // Steps:
    // 1. Try to parse as YAML Value.
    // 2. If YAML error, return error with prefix "error: xplr -m: yaml: " + yaml error
    // 3. Convert YAML Value to JSON Value, then to compact JSON string.
    // 4. Try to parse JSON string into Message via serde_json.
    //    If fails, return error as from serde_json (e.g., "error: unknown variant ..." or "error: invalid type: ...")
    //    Note: original errors for invalid type and unknown variant have no "xplr -m:" prefix, just "error: ..."
    // 5. On success, return JSON string.

    let yaml_value: Result<serde_yaml::Value, _> = serde_yaml::from_str(yaml_str);
    let yaml_value = match yaml_value {
        Ok(v) => v,
        Err(e) => {
            return Err(format!("error: xplr -m: yaml: {}\n", e));
        }
    };

    // Convert to JSON value
    let json_value = match serde_json::to_value(&yaml_value) {
        Ok(v) => v,
        Err(e) => {
            // Should not happen, but treat as yaml error?
            return Err(format!("error: xplr -m: yaml: {}\n", e));
        }
    };

    let json_str = serde_json::to_string(&json_value).unwrap();

    // Now try to deserialize json_str into Message
    let msg_res: Result<Message, _> = serde_json::from_str(&json_str);
    match msg_res {
        Ok(_) => Ok(json_str),
        Err(e) => {
            // e is serde_json::Error, includes line/col
            // Original errors for this case are like "error: unknown variant `...`..." or "error: invalid type: ..."
            // The error Display already includes at line/col
            return Err(format!("error: {}\n", e));
        }
    }
}

fn parse_message_for_on_load(yaml_str: &str) -> Result<(), String> {
    // For on-load, similar but without placeholder processing, and errors are not prefixed with xplr -m.
    // The YAML parsing error should be "error: <yaml error>"
    // Unknown variant etc also "error: ..."
    let yaml_value: Result<serde_yaml::Value, _> = serde_yaml::from_str(yaml_str);
    let yaml_value = match yaml_value {
        Ok(v) => v,
        Err(e) => {
            return Err(format!("error: {}\n", e));
        }
    };
    let json_value = serde_json::to_value(&yaml_value).unwrap();
    let json_str = serde_json::to_string(&json_value).unwrap();
    let msg_res: Result<Message, _> = serde_json::from_str(&json_str);
    match msg_res {
        Ok(_) => Ok(()),
        Err(e) => Err(format!("error: {}\n", e)),
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    // args[0] is binary name

    // Early handling for -m and -M usage errors? We'll parse sequentially.

    // We need to handle help and version with precedence? Let's check original behavior:
    // -h and --help print help if no path existence error and no invalid arg? Actually -h with valid path prints help, with invalid path prints path doesn't exist error.
    // Similarly -V with valid/invalid path? For -V with invalid path we saw path doesn't exist error, not version. So path existence check takes precedence over help/version when path doesn't exist?
    // Wait earlier we had -h /nonexistent gave path doesn't exist, not help. So path existence error takes precedence over help? But -h /tmp gave help, not ENODEV. So when path exists, help takes precedence over TUI. When path doesn't exist, path error takes precedence over help.

    // So order: first check for invalid arguments, then check for missing values for single-value options, then check file existence for those options, then check for help/version? Or help/version after existence?

    // Let's attempt to implement parsing that matches observed:
    // - For help/version flags that appear anywhere before any path existence error? Actually we saw "-h -M FocusNext" gave help, so help before -M takes precedence. But "-h /nonexistent" gave path doesn't exist, not help. So help with subsequent path that doesn't exist gives path error, not help. So path error after help still matters? That suggests parsing goes left to right, and if help encountered, but later path doesn't exist, path error overrides? But "-h /tmp" gave help, not ENODEV, so existing path doesn't override help.

    // Could be that help/version are checked after all other parsing, but path existence is checked before help? However "-h /tmp" should then give path doesn't exist? No, /tmp exists, so path existence passes, then help printed. For "/nonexistent", path existence fails, so error before help.

    // Let's try to model:

    // We have a list of tokens. We need to parse options and their values, and collect positional args (PATH and SELECTION).

    // Steps:
    // - Initialize index =1
    // - While index < args.len():
    //   - If arg == "--": then all remaining args are positional (PATH, SELECTION). Break and collect them.
    //   - Else if arg == "-" (single dash): boolean flag, set flag dash = true.
    //   - Else if arg == "-h" or "--help": mark help flag.
    //   - Else if arg == "-V" or "--version": mark version flag.
    //   - Else if arg == "-m" or "--pipe-msg-in": this is special. Need to check if next arg exists, else usage error. If exists, format = next arg, placeholder args = remaining args (all). Then handle -m logic immediately? And ignore further parsing?
    //   - Else if arg == "-M" or "--print-msg-in": similar.
    //   - Else if arg == "-c" or "--config": expects one value. If missing, usage error. Else check existence of that path, collect as config.
    //   - Else if arg == "-C" or "--extra-config": multi-value. It can have 0+ values. How to parse? We need to consume following args that are not flags? But original allows values that look like paths, and stops when encounters flag or -- or end. So we need to collect while next arg exists and does not start with "-" or is "--"? Actually what about arg that starts with "-" but is a path like "-h" as path after --? After --, it's positional. Before --, if arg starts with "-" it's considered flag, not value, unless it's the value for -c which can be "-h" as we saw: "-c -h" took "-h" as config path and gave path doesn't exist error, not help. So for single-value options, the next arg is taken as value even if it looks like flag (like "-h").
    //        For multi-value options like -C and --on-load, they take values that are not flags? Let's see: "-C -h" gave help, not path error, meaning "-h" was NOT taken as extra-config value, but as help flag. So multi-value options do NOT take flag-like args as values; they stop.
    //        Similarly "--on-load -h" gave help.
    //   - Else if arg == "--vroot": single-value, similar to -c: takes next arg even if flag-like? Let's test: "--vroot -h" gave path doesn't exist error for "-h", not help. So single-value --vroot does take flag-like as value.
    //   - Else if arg == "--on-load": multi-value, similar to -C: stops at flag.
    //   - Else if arg == "--force-focus", "--print-pwd-as-result", "--read-only", "--read0", "--write0", "-0", "--null": boolean flags.
    //   - Else if arg starts with "-": invalid argument.
    //   - Else: positional arg (PATH or SELECTION).
    // - After parsing, we have help flag, version flag, config paths, extra-config paths, on-load messages, vroot path, other boolean flags, and positional paths.

    // For our simplified reimplementation, we need to handle all these.

    // Let's attempt to implement parsing loop with state.

    let mut i = 1;
    let mut help_flag = false;
    let mut version_flag = false;
    let mut config_path: Option<String> = None;
    let mut extra_config_paths: Vec<String> = Vec::new();
    let mut on_load_messages: Vec<String> = Vec::new();
    let mut vroot_path: Option<String> = None;
    let mut positional_paths: Vec<String> = Vec::new();
    let mut has_dash_flag = false;
    let mut ended = false;

    // For checking invalid args, we need to detect unknown flags.
    // Known flags list.

    while i < args.len() {
        let arg = &args[i];
        if ended {
            positional_paths.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            ended = true;
            i += 1;
            continue;
        }
        if arg == "-" {
            has_dash_flag = true;
            i += 1;
            continue;
        }
        if arg == "-h" || arg == "--help" {
            help_flag = true;
            i += 1;
            continue;
        }
        if arg == "-V" || arg == "--version" {
            version_flag = true;
            i += 1;
            continue;
        }
        if arg == "-m" || arg == "--pipe-msg-in" {
            // Check if next arg exists
            if i + 1 >= args.len() {
                eprint!("error: usage: xplr {} FORMAT [ARGUMENT]...\n", arg);
                std::process::exit(1);
            }
            let format = args[i+1].clone();
            let placeholder_args: Vec<String> = args[i+2..].to_vec();
            // Before handling, we should have already checked for invalid args and file existence for prior options.
            // But also need to check config and vroot existence that were already parsed (they were).
            // Now handle -m
            match format_template(&format, &placeholder_args) {
                Ok(formatted) => {
                    match parse_message(&formatted) {
                        Ok(json_str) => {
                            // Handle pipe
                            // Check env var
                            let pipe_path = env::var("XPLR_PIPE_MSG_IN").unwrap_or_default();
                            if pipe_path.is_empty() {
                                // Print with newline
                                println!("{}", json_str);
                                std::process::exit(0);
                            } else {
                                // Check file existence
                                let path = Path::new(&pipe_path);
                                if !path.exists() {
                                    eprint!("error: No such file or directory (os error 2)\n");
                                    std::process::exit(1);
                                }
                                // Read file
                                let content = match fs::read(path) {
                                    Ok(c) => c,
                                    Err(e) => {
                                        eprint!("error: {}\n", e);
                                        std::process::exit(1);
                                    }
                                };
                                if content.is_empty() {
                                    eprint!("error: failed to detect delimmiter\n");
                                    std::process::exit(1);
                                }
                                let delim = content[0];
                                // Append
                                let mut file_content = content;
                                file_content.extend_from_slice(json_str.as_bytes());
                                file_content.push(delim);
                                if let Err(e) = fs::write(path, file_content) {
                                    eprint!("error: {}\n", e);
                                    std::process::exit(1);
                                }
                                std::process::exit(0);
                            }
                        }
                        Err(e) => {
                            eprint!("{}", e);
                            std::process::exit(1);
                        }
                    }
                }
                Err(e) => {
                    eprint!("{}", e);
                    std::process::exit(1);
                }
            }
        }
        if arg == "-M" || arg == "--print-msg-in" {
            if i + 1 >= args.len() {
                eprint!("error: usage: xplr {} FORMAT [ARGUMENT]...\n", arg);
                std::process::exit(1);
            }
            let format = args[i+1].clone();
            let placeholder_args: Vec<String> = args[i+2..].to_vec();
            match format_template(&format, &placeholder_args) {
                Ok(formatted) => {
                    match parse_message(&formatted) {
                        Ok(json_str) => {
                            print!("{}", json_str);
                            std::process::exit(0);
                        }
                        Err(e) => {
                            eprint!("{}", e);
                            std::process::exit(1);
                        }
                    }
                }
                Err(e) => {
                    eprint!("{}", e);
                    std::process::exit(1);
                }
            }
        }
        // Single-value options
        if arg == "-c" || arg == "--config" {
            if i + 1 >= args.len() {
                let name = if arg == "-c" { "-c" } else { "--config" };
                eprint!("error: usage: xplr {} PATH\n", name);
                std::process::exit(1);
            }
            let val = args[i+1].clone();
            // Check existence immediately? Original checks existence and prints path doesn't exist error.
            if !Path::new(&val).exists() {
                eprint!("error: path doesn't exist: {}\n", val);
                std::process::exit(1);
            }
            config_path = Some(val);
            i += 2;
            continue;
        }
        if arg == "--vroot" {
            if i + 1 >= args.len() {
                eprint!("error: usage: xplr --vroot PATH\n");
                std::process::exit(1);
            }
            let val = args[i+1].clone();
            if !Path::new(&val).exists() {
                eprint!("error: path doesn't exist: {}\n", val);
                std::process::exit(1);
            }
            vroot_path = Some(val);
            i += 2;
            continue;
        }
        // Multi-value options
        if arg == "-C" || arg == "--extra-config" {
            // Consume following args that are not flags (don't start with -) and not --?
            // Actually need to check: if next arg starts with "-" but is not "--" and is not a known flag value that could be taken as path for single-value? For multi-value, we should stop when encountering flag.
            // Simplified: while next arg exists and does not start with "-" OR next arg is "-" (dash flag is boolean, but could be value? For extra-config, "-" as value would be weird). We'll check: if next arg starts with "-" then break.
            i += 1;
            while i < args.len() {
                let next = &args[i];
                if next == "--" {
                    break;
                }
                if next.starts_with('-') {
                    break;
                }
                // It's a path, check existence
                if !Path::new(next).exists() {
                    eprint!("error: path doesn't exist: {}\n", next);
                    std::process::exit(1);
                }
                extra_config_paths.push(next.clone());
                i += 1;
            }
            continue;
        }
        if arg == "--on-load" {
            i += 1;
            while i < args.len() {
                let next = &args[i];
                if next == "--" {
                    break;
                }
                if next.starts_with('-') {
                    break;
                }
                // Validate as message
                match parse_message_for_on_load(next) {
                    Ok(_) => {},
                    Err(e) => {
                        eprint!("{}", e);
                        std::process::exit(1);
                    }
                }
                on_load_messages.push(next.clone());
                i += 1;
            }
            continue;
        }
        // Boolean flags
        if arg == "--force-focus" || arg == "--print-pwd-as-result" || arg == "--read-only" || arg == "--read0" || arg == "--write0" || arg == "-0" || arg == "--null" {
            i += 1;
            continue;
        }
        // If starts with '-', invalid
        if arg.starts_with('-') {
            eprint!("error: invalid argument: \"{}\", try `-- \"{}\"` or `--help`\n", arg, arg);
            std::process::exit(1);
        }
        // Positional
        positional_paths.push(arg.clone());
        i += 1;
    }

    // After parsing, check path existence for positional
    for p in &positional_paths {
        if !Path::new(p).exists() {
            eprint!("error: path doesn't exist: {}\n", p);
            std::process::exit(1);
        }
    }

    // If help flag set, print help and exit 0 (if no path existence error already)
    if help_flag {
        print!("{}", HELP_TEXT);
        std::process::exit(0);
    }
    if version_flag {
        print!("{}", VERSION_TEXT);
        std::process::exit(0);
    }

    // If we reach here, it means no -m/-M, no help/version, and all paths exist (or none). Original would try to start TUI and fail with ENODEV when no TTY.
    eprint!("error: No such device or address (os error 6)\n");
    std::process::exit(1);
}
