// Ideally we should have precise types, but using String will cause some variants to accept any string, which may not match original's complex validation.
// However, for our simplified implementation, let's keep String for complex ones and handle.

fn format_template(template: &str, args: &[String]) -> Result<String, String> {
    // Returns formatted YAML string or error message (without prefix)
    let mut result = String::new();
    let mut arg_idx = 0;
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '%' {
            if i + 1 >= chars.len() {
                return Err(format!("error: xplr -m: template ended with incomplete placeholder\n"));
            }
            let next = chars[i + 1];
            match next {
                '%' => {
                    result.push('%');
                    i += 2;
                }
                's' => {
                    if arg_idx >= args.len() {
                        // column is 1-indexed position of % in original template
                        // Compute column by char count up to i (but need byte column? Original counts bytes? We have char count as bytes for ascii)
                        let col = template[..i].chars().count() + 1;
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col));
                    }
                    result.push_str(&args[arg_idx]);
                    arg_idx += 1;
                    i += 2;
                }
                'q' => {
                    if arg_idx >= args.len() {
                        let col = template[..i].chars().count() + 1;
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col));
                    }
                    // quoted: use json string
                    let quoted = serde_json::to_string(&args[arg_idx]).unwrap_or_else(|_| "\"\"".to_string());
                    result.push_str(&quoted);
                    arg_idx += 1;
                    i += 2;
                }
                _ => {
                    let col = template[..i].chars().count() + 1;
                    // The placeholder is e.g., "% " or "%x" - we need to include the two chars
                    let ph = format!("%{}", next);
                    return Err(format!("error: xplr -m: invalid placeholder '{}' at column {}, use one of '%s' or '%q', or escape it using '%%'\n", ph, col));
                }
            }
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }
    if arg_idx < args.len() {
        return Err(format!("error: xplr -m: too many positional values, not enough positional placeholders\n"));
    }
    Ok(result)
}

fn parse_message(yaml_str: &str) -> Result<String, String> {
    // yaml_str is formatted YAML (or JSON) template result.
    // Steps:
    // 1. Try to parse as YAML Value.
    // 2. If YAML error, return error with prefix "error: xplr -m: yaml: " + yaml error
    // 3. Convert YAML Value to JSON Value, then to compact JSON string.
    // 4. Try to parse JSON string into Message via serde_json.
    //    If fails, return error as from serde_json (e.g., "error: unknown variant ..." or "error: invalid type: ...")
    //    Note: original errors for invalid type and unknown variant have no "xplr -m:" prefix, just "error: ..."
    // 5. On success, return JSON string.

    let yaml_value: Result<serde_yaml::Value, _> = serde_yaml::from_str(yaml_str);
    let yaml_value = match yaml_value {
        Ok(v) => v,
        Err(e) => {
            return Err(format!("error: xplr -m: yaml: {}\n", e));
        }
    };

    // Convert to JSON value
    let json_value = match serde_json::to_value(&yaml_value) {
        Ok(v) => v,
        Err(e) => {
            // Should not happen, but treat as yaml error?
            return Err(format!("error: xplr -m: yaml: {}\n", e));
        }
    };

    let json_str = serde_json::to_string(&json_value).unwrap();

    // Now try to deserialize json_str into Message
    let msg_res: Result<Message, _> = serde_json::from_str(&json_str);
    match msg_res {
        Ok(_) => Ok(json_str),
        Err(e) => {
            // e is serde_json::Error, includes line/col
            // Original errors for this case are like "error: unknown variant `...`..." or "error: invalid type: ..."
            // The error Display already includes at line/col
            return Err(format!("error: {}\n", e));
        }
    }
}

fn parse_message_for_on_load(yaml_str: &str) -> Result<(), String> {
    // For on-load, similar but without placeholder processing, and errors are not prefixed with xplr -m.
    // The YAML parsing error should be "error: <yaml error>"
    // Unknown variant etc also "error: ..."
    let yaml_value: Result<serde_yaml::Value, _> = serde_yaml::from_str(yaml_str);
    let yaml_value = match yaml_value {
        Ok(v) => v,
        Err(e) => {
            return Err(format!("error: {}\n", e));
        }
    };
    let json_value = serde_json::to_value(&yaml_value).unwrap();
    let json_str = serde_json::to_string(&json_value).unwrap();
    let msg_res: Result<Message, _> = serde_json::from_str(&json_str);
    match msg_res {
        Ok(_) => Ok(()),
        Err(e) => Err(format!("error: {}\n", e)),
    }
}

