        if arg == "-c" || arg == "--config" {
            if i + 1 >= args.len() {
                let name = if arg == "-c" { "-c" } else { "--config" };
                eprint!("error: usage: xplr {} PATH\n", name);
                std::process::exit(1);
            }
            let val = args[i+1].clone();
            // Check existence immediately? Original checks existence and prints path doesn't exist error.
            if !Path::new(&val).exists() {
                eprint!("error: path doesn't exist: {}\n", val);
                std::process::exit(1);
            }
            config_path = Some(val);
            i += 2;
            continue;
        }
        if arg == "--vroot" {
            if i + 1 >= args.len() {
                eprint!("error: usage: xplr --vroot PATH\n");
                std::process::exit(1);
            }
            let val = args[i+1].clone();
            if !Path::new(&val).exists() {
                eprint!("error: path doesn't exist: {}\n", val);
                std::process::exit(1);
            }
            vroot_path = Some(val);
            i += 2;
            continue;
        }
        // Multi-value options
        if arg == "-C" || arg == "--extra-config" {
            // Consume following args that are not flags (don't start with -) and not --?
            // Actually need to check: if next arg starts with "-" but is not "--" and is not a known flag value that could be taken as path for single-value? For multi-value, we should stop when encountering flag.
            // Simplified: while next arg exists and does not start with "-" OR next arg is "-" (dash flag is boolean, but could be value? For extra-config, "-" as value would be weird). We'll check: if next arg starts with "-" then break.
            i += 1;
            while i < args.len() {
                let next = &args[i];
                if next == "--" {
                    break;
                }
                if next.starts_with('-') {
                    break;
                }
                // It's a path, check existence
                if !Path::new(next).exists() {
                    eprint!("error: path doesn't exist: {}\n", next);
                    std::process::exit(1);
                }
                extra_config_paths.push(next.clone());
                i += 1;
            }
            continue;
        }
        if arg == "--on-load" {
            i += 1;
            while i < args.len() {
                let next = &args[i];
                if next == "--" {
                    break;
                }
                if next.starts_with('-') {
                    break;
                }
                // Validate as message
                match parse_message_for_on_load(next) {
                    Ok(_) => {},
                    Err(e) => {
                        eprint!("{}", e);
                        std::process::exit(1);
                    }
                }
                on_load_messages.push(next.clone());
                i += 1;
            }
            continue;
        }
        // Boolean flags
        if arg == "--force-focus" || arg == "--print-pwd-as-result" || arg == "--read-only" || arg == "--read0" || arg == "--write0" || arg == "-0" || arg == "--null" {
            i += 1;
            continue;
        }
        // If starts with '-', invalid
        if arg.starts_with('-') {
            eprint!("error: invalid argument: \"{}\", try `-- \"{}\"` or `--help`\n", arg, arg);
            std::process::exit(1);
        }
        // Positional
        positional_paths.push(arg.clone());
        i += 1;
    }

    // After parsing, check path existence for positional
    for p in &positional_paths {
        if !Path::new(p).exists() {
            eprint!("error: path doesn't exist: {}\n", p);
            std::process::exit(1);
        }
    }

    // If help flag set, print help and exit 0 (if no path existence error already)
    if help_flag {
        print!("{}", HELP_TEXT);
        std::process::exit(0);
    }
    if version_flag {
        print!("{}", VERSION_TEXT);
        std::process::exit(0);
    }

    // If we reach here, it means no -m/-M, no help/version, and all paths exist (or none). Original would try to start TUI and fail with ENODEV when no TTY.
    eprint!("error: No such device or address (os error 6)\n");
    std::process::exit(1);
}
