fn format_template(template: &str, args: &[String]) -> Result<String, String> {
    let mut result = String::new();
    let mut arg_idx = 0;
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '%' {
            if i + 1 >= chars.len() {
                return Err(format!("error: xplr -m: template ended with incomplete placeholder\n"));
            }
            let next = chars[i + 1];
            match next {
                '%' => {
                    result.push('%');
                    i += 2;
                }
                's' => {
                    if arg_idx >= args.len() {
                        let col = template[..i].chars().count() + 1;
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col));
                    }
                    result.push_str(&args[arg_idx]);
                    arg_idx += 1;
                    i += 2;
                }
                'q' => {
                    if arg_idx >= args.len() {
                        let col = template[..i].chars().count() + 1;
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col));
                    }
                    let quoted = serde_json::to_string(&args[arg_idx]).unwrap_or_else(|_| "\"\"".to_string());
                    result.push_str(&quoted);
                    arg_idx += 1;
                    i += 2;
                }
                _ => {
                    let col = template[..i].chars().count() + 1;
                    let ph = format!("%{}", next);
                    return Err(format!("error: xplr -m: invalid placeholder '{}' at column {}, use one of '%s' or '%q', or escape it using '%%'\n", ph, col));
                }
            }
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }
    if arg_idx < args.len() {
        return Err(format!("error: xplr -m: too many positional values, not enough positional placeholders\n"));
    }
    Ok(result)
}

fn parse_message(yaml_str: &str) -> Result<String, String> {
    let yaml_value: Result<serde_yaml::Value, _> = serde_yaml::from_str(yaml_str);
    let yaml_value = match yaml_value {
        Ok(v) => v,
        Err(e) => {
            return Err(format!("error: xplr -m: yaml: {}\n", e));
        }
    };
    let json_value = serde_json::to_value(&yaml_value).unwrap();
    let json_str = serde_json::to_string(&json_value).unwrap();
    let msg_res: Result<Message, _> = serde_json::from_str(&json_str);
    match msg_res {
        Ok(_) => Ok(json_str),
        Err(e) => Err(format!("error: {}\n", e)),
    }
}

fn parse_message_for_on_load(yaml_str: &str) -> Result<(), String> {
    // Use serde_yaml directly, but to allow string coercion for LogSuccess etc, we need to use a permissive approach.
    // We will first check if yaml_str is valid YAML.
    let yaml_value: Result<serde_yaml::Value, _> = serde_yaml::from_str(yaml_str);
    let yaml_value = match yaml_value {
        Ok(v) => v,
        Err(e) => return Err(format!("error: {}\n", e)),
    };

    // For unknown variant errors, we need to get the list. Using Message via serde_yaml will give "invalid type: map, expected a YAML tag..." for newtype variants, not unknown variant.
    // So we need manual check for unknown variant.

    // Extract variant name
    let variant_name = match &yaml_value {
        serde_yaml::Value::String(s) => s.clone(),
        serde_yaml::Value::Mapping(m) => {
            if m.len() != 1 {
                // For mapping with more than one key? Original would probably error as unknown? But we will try to deserialize to Message via JSON strict to get proper error.
                // Use JSON path
                let json_value = serde_json::to_value(&yaml_value).unwrap();
                let json_str = serde_json::to_string(&json_value).unwrap();
                let res: Result<Message, _> = serde_json::from_str(&json_str);
                match res {
                    Ok(_) => return Ok(()),
                    Err(e) => {
                        let es = e.to_string();
                        // If error is about expected string but got integer etc for LogSuccess, we consider valid for on-load
                        if es.contains("expected a string") && (es.contains("integer") || es.contains("boolean") || es.contains("floating point") || es.contains("null") || es.contains("expected unit") == false) {
                            // Actually for string expected, integer etc should be considered valid for on-load (coerced)
                            if es.contains("expected a string") {
                                return Ok(());
                            }
                        }
                        // For other errors, try YAML direct to get correct column
                        let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                        match yres {
                            Ok(_) => return Ok(()),
                            Err(ye) => return Err(format!("error: {}\n", ye)),
                        }
                    }
                }
            }
            // Get first key
            let (k, _) = m.iter().next().unwrap();
            match k {
                serde_yaml::Value::String(s) => s.clone(),
                _ => {
                    // key not string?
                    let json_value = serde_json::to_value(&yaml_value).unwrap();
                    let json_str = serde_json::to_string(&json_value).unwrap();
                    let res: Result<Message, _> = serde_json::from_str(&json_str);
                    return match res {
                        Ok(_) => Ok(()),
                        Err(e) => Err(format!("error: {}\n", e)),
                    }
                }
            }
        }
        _ => {
            // For other types (e.g., number, bool), treat as unknown? Let's try JSON path
            let json_value = serde_json::to_value(&yaml_value).unwrap();
            let json_str = serde_json::to_string(&json_value).unwrap();
            let res: Result<Message, _> = serde_json::from_str(&json_str);
            return match res {
                Ok(_) => Ok(()),
                Err(e) => Err(format!("error: {}\n", e)),
            }
        }
    };

    // Check if variant_name is known
    let known_variants = [
        "ExplorePwd","ExplorePwdAsync","ExploreParentsAsync","TryCompletePath","ClearScreen","Refresh","FocusNext","FocusNextSelection","FocusNextByRelativeIndex","FocusNextByRelativeIndexFromInput","FocusPrevious","FocusPreviousSelection","FocusPreviousByRelativeIndex","FocusPreviousByRelativeIndexFromInput","FocusFirst","FocusLast","FocusPath","FocusPathFromInput","FocusByIndex","FocusByIndexFromInput","FocusByFileName","ScrollUp","ScrollDown","ScrollUpHalf","ScrollDownHalf","ChangeDirectory","Enter","Back","LastVisitedPath","NextVisitedPath","PreviousVisitedDeepBranch","NextVisitedDeepBranch","FollowSymlink","SetVroot","UnsetVroot","ToggleVroot","ResetVroot","SetInputPrompt","UpdateInputBuffer","UpdateInputBufferFromKey","BufferInput","BufferInputFromKey","SetInputBuffer","RemoveInputBufferLastCharacter","RemoveInputBufferLastWord","ResetInputBuffer","SwitchMode","SwitchModeKeepingInputBuffer","SwitchModeBuiltin","SwitchModeBuiltinKeepingInputBuffer","SwitchModeCustom","SwitchModeCustomKeepingInputBuffer","PopMode","PopModeKeepingInputBuffer","SwitchLayout","SwitchLayoutBuiltin","SwitchLayoutCustom","Call","Call0","CallSilently","CallSilently0","BashExec","BashExec0","BashExecSilently","BashExecSilently0","CallLua","CallLuaSilently","LuaEval","LuaEvalSilently","Select","SelectAll","SelectPath","UnSelect","UnSelectAll","UnSelectPath","ToggleSelection","ToggleSelectAll","ToggleSelectionByPath","ClearSelection","AddNodeFilter","RemoveNodeFilter","ToggleNodeFilter","AddNodeFilterFromInput","RemoveNodeFilterFromInput","RemoveLastNodeFilter","ResetNodeFilters","ClearNodeFilters","AddNodeSorter","RemoveNodeSorter","ReverseNodeSorter","ToggleNodeSorter","ReverseNodeSorters","RemoveLastNodeSorter","ResetNodeSorters","ClearNodeSorters","Search","SearchFromInput","SearchFuzzy","SearchFuzzyFromInput","SearchFuzzyUnordered","SearchFuzzyUnorderedFromInput","SearchRegex","SearchRegexFromInput","SearchRegexUnordered","SearchRegexUnorderedFromInput","ToggleSearchAlgorithm","EnableSearchOrder","DisableSearchOrder","ToggleSearchOrder","AcceptSearch","CancelSearch","EnableMouse","DisableMouse","ToggleMouse","StartFifo","StopFifo","ToggleFifo","LogInfo","LogSuccess","LogWarning","LogError","Debug","Quit","PrintPwdAndQuit","PrintFocusPathAndQuit","PrintSelectionAndQuit","PrintResultAndQuit","PrintAppStateAndQuit","Terminate",
    ];

    if !known_variants.contains(&variant_name.as_str()) {
        // Try to get unknown variant error via serde_json for mapping or string
        let json_value = serde_json::to_value(&yaml_value).unwrap();
        let json_str = serde_json::to_string(&json_value).unwrap();
        let res: Result<Message, _> = serde_json::from_str(&json_str);
        match res {
            Ok(_) => return Ok(()),
            Err(e) => {
                // For on-load, unknown variant error should NOT have column suffix? Actually for simple string "invalid" original had no column, but for "Invalid: foo" it had unknown variant without column? Let's check: earlier --on-load "Invalid: foo" gave unknown variant without column? We saw it gave unknown variant without column? Actually it gave 2518? Let's see, but we can just return error as is, but need to decide if we should strip column suffix for on-load.
                // Our earlier test: --on-load invalid gave error without column, but -M invalid gave with column. So for on-load, we should NOT include column for unknown variant? Let's check: --on-load invalid error we saw had no column, just ends with Terminate. For -M invalid, it had " at line 1 column 9".
                // So we need to strip the " at line..." suffix for on-load unknown variant errors?
                // Actually serde_json error for unknown variant includes " at line 1 column X". For on-load, original omits it. How?
                // Let's see: --on-load invalid gave 2518 chars without column, -M invalid gave 2537 with column. So on-load strips column suffix.

                // Similarly, for FocusByIndex abc, on-load error includes column 15 with variant prefix "FocusByIndex: ...", while -M error includes column 21 without variant prefix? Let's check:
                // -M FocusByIndex abc gave "error: invalid type: string "abc", expected usize at line 1 column 21" (no variant prefix)
                // --on-load FocusByIndex abc gave "error: FocusByIndex: invalid type: string "abc", expected usize at line 1 column 15" (with variant prefix)

                // So on-load errors for invalid type include variant prefix and column at value start, while -M errors have no prefix and column at JSON location.

                // Our current approach for on-load using serde_yaml direct gave "FocusByIndex: invalid type: string "abc", expected usize at line 1 column 15" which matches original! Good.

                // For unknown variant via serde_yaml direct, what error does it give? Let's test: serde_yaml from_str for Message direct for "invalid" gives map error, not unknown variant. So we need to use serde_json for unknown variant but strip column for on-load.

                // Let's handle unknown variant specially: if error contains "unknown variant", strip the " at line 1 column X" suffix for on-load.

                let mut err_str = e.to_string();
                // For on-load, strip column suffix if present? Original on-load invalid had no column suffix, so we should strip.
                if let Some(idx) = err_str.find(" at line") {
                    err_str = err_str[..idx].to_string();
                }
                return Err(format!("error: {}\n", err_str));
            }
        }
    }

    // If variant known, check expected type
    // For simplicity, we will try to deserialize via serde_yaml using a permissive struct that allows string coercion for String variants.

    // For String-expected variants, we will allow any scalar (string, number, bool, null) to be valid.
    // For usize-expected variants, we require number that is integer, else error with appropriate message.

    // Let's define expected type mapping
    let string_variants = [
        "FocusPath","FocusByFileName","ChangeDirectory","SetVroot","SetInputPrompt","BufferInput","SetInputBuffer","SwitchMode","SwitchModeKeepingInputBuffer","SwitchModeBuiltin","SwitchModeBuiltinKeepingInputBuffer","SwitchModeCustom","SwitchModeCustomKeepingInputBuffer","SwitchLayout","SwitchLayoutBuiltin","SwitchLayoutCustom","BashExec","BashExec0","BashExecSilently","BashExecSilently0","CallLua","CallLuaSilently","LuaEval","LuaEvalSilently","SelectPath","UnSelectPath","ToggleSelectionByPath","Search","SearchFuzzy","SearchFuzzyUnordered","SearchRegex","SearchRegexUnordered","StartFifo","ToggleFifo","LogInfo","LogSuccess","LogWarning","LogError","Debug",
    ];
    let usize_variants = [
        "FocusNextByRelativeIndex","FocusPreviousByRelativeIndex","FocusByIndex",
    ];

    // Check if variant is unit (no data expected)
    let unit_variants = [
        "ExplorePwd","ExplorePwdAsync","ExploreParentsAsync","TryCompletePath","ClearScreen","Refresh","FocusNext","FocusNextSelection","FocusNextByRelativeIndexFromInput","FocusPrevious","FocusPreviousSelection","FocusPreviousByRelativeIndexFromInput","FocusFirst","FocusLast","FocusPathFromInput","FocusByIndexFromInput","ScrollUp","ScrollDown","ScrollUpHalf","ScrollDownHalf","Enter","Back","LastVisitedPath","NextVisitedPath","PreviousVisitedDeepBranch","NextVisitedDeepBranch","FollowSymlink","UnsetVroot","ToggleVroot","ResetVroot","UpdateInputBufferFromKey","BufferInputFromKey","RemoveInputBufferLastCharacter","RemoveInputBufferLastWord","ResetInputBuffer","PopMode","PopModeKeepingInputBuffer","Select","SelectAll","UnSelect","UnSelectAll","ToggleSelection","ToggleSelectAll","ClearSelection","RemoveLastNodeFilter","ResetNodeFilters","ClearNodeFilters","ReverseNodeSorters","RemoveLastNodeSorter","ResetNodeSorters","ClearNodeSorters","SearchFromInput","SearchFuzzyFromInput","SearchFuzzyUnorderedFromInput","SearchRegexFromInput","SearchRegexUnorderedFromInput","ToggleSearchAlgorithm","EnableSearchOrder","DisableSearchOrder","ToggleSearchOrder","AcceptSearch","CancelSearch","EnableMouse","DisableMouse","ToggleMouse","StopFifo","Quit","PrintPwdAndQuit","PrintFocusPathAndQuit","PrintSelectionAndQuit","PrintResultAndQuit","PrintAppStateAndQuit","Terminate",
    ];

    match &yaml_value {
        serde_yaml::Value::String(s) => {
            // s is the variant name itself (e.g., "FocusNext")
            if unit_variants.contains(&s.as_str()) {
                return Ok(());
            } else if string_variants.contains(&s.as_str()) || usize_variants.contains(&s.as_str()) {
                // Expected newtype but got unit -> error "invalid type: unit variant, expected newtype variant" etc.
                // Original for FocusPath (expects String) but got unit "FocusPath" gave "invalid type: unit variant, expected newtype variant"
                // Let's try to get that error via serde_yaml direct
                let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                return match yres {
                    Ok(_) => Ok(()),
                    Err(e) => Err(format!("error: {}\n", e)),
                }
            } else {
                // Unknown already handled
                return Ok(());
            }
        }
        serde_yaml::Value::Mapping(m) => {
            if m.len() != 1 {
                // Try JSON path for complex?
                let json_value = serde_json::to_value(&yaml_value).unwrap();
                let json_str = serde_json::to_string(&json_value).unwrap();
                let res: Result<Message, _> = serde_json::from_str(&json_str);
                match res {
                    Ok(_) => return Ok(()),
                    Err(e) => {
                        // For on-load, if expected string but got integer etc, we already considered valid, but for other errors return
                        let es = e.to_string();
                        if es.contains("expected a string") && (es.contains("integer") || es.contains("boolean") || es.contains("null") || es.contains("floating point")) {
                            return Ok(());
                        }
                        let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                        return match yres {
                            Ok(_) => Ok(()),
                            Err(ye) => Err(format!("error: {}\n", ye)),
                        }
                    }
                }
            }
            let (k, v) = m.iter().next().unwrap();
            let key_str = match k {
                serde_yaml::Value::String(s) => s.clone(),
                _ => {
                    let json_value = serde_json::to_value(&yaml_value).unwrap();
                    let json_str = serde_json::to_string(&json_value).unwrap();
                    let res: Result<Message, _> = serde_json::from_str(&json_str);
                    return match res {
                        Ok(_) => Ok(()),
                        Err(e) => Err(format!("error: {}\n", e)),
                    }
                }
            };

            if unit_variants.contains(&key_str.as_str()) {
                // Unit variant should not have value, but we have mapping with value -> should be error "invalid type: map, expected unit variant" or similar
                let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                return match yres {
                    Ok(_) => Ok(()),
                    Err(e) => Err(format!("error: {}\n", e)),
                }
            } else if string_variants.contains(&key_str.as_str()) {
                // Expect String, accept any scalar
                match v {
                    serde_yaml::Value::String(_) | serde_yaml::Value::Number(_) | serde_yaml::Value::Bool(_) | serde_yaml::Value::Null => return Ok(()),
                    _ => {
                        // For complex value like mapping, try to get error
                        let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                        return match yres {
                            Ok(_) => Ok(()),
                            Err(e) => Err(format!("error: {}\n", e)),
                        }
                    }
                }
            } else if usize_variants.contains(&key_str.as_str()) {
                // Expect usize
                match v {
                    serde_yaml::Value::Number(n) => {
                        if n.is_u64() || n.is_i64() {
                            return Ok(());
                        } else {
                            // float
                            let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                            return match yres {
                                Ok(_) => Ok(()),
                                Err(e) => Err(format!("error: {}\n", e)),
                            }
                        }
                    }
                    serde_yaml::Value::String(_) => {
                        let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                        return match yres {
                            Ok(_) => Ok(()),
                            Err(e) => Err(format!("error: {}\n", e)),
                        }
                    }
                    _ => {
                        let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                        return match yres {
                            Ok(_) => Ok(()),
                            Err(e) => Err(format!("error: {}\n", e)),
                        }
                    }
                }
            } else {
                // For complex variants like Call, AddNodeFilter etc, just try YAML direct
                let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                return match yres {
                    Ok(_) => Ok(()),
                    Err(e) => Err(format!("error: {}\n", e)),
                }
            }
        }
        _ => {
            let json_value = serde_json::to_value(&yaml_value).unwrap();
            let json_str = serde_json::to_string(&json_value).unwrap();
            let res: Result<Message, _> = serde_json::from_str(&json_str);
            return match res {
                Ok(_) => Ok(()),
                Err(e) => Err(format!("error: {}\n", e)),
            }
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut i = 1;
    let mut help_flag = false;
    let mut version_flag = false;
    let mut positional_paths: Vec<String> = Vec::new();
    let mut ended = false;

    while i < args.len() {
        let arg = &args[i];
        if ended {
            positional_paths.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            ended = true;
            i += 1;
            continue;
        }
        if arg == "-" {
            i += 1;
            continue;
        }
        if arg == "-h" || arg == "--help" {
            help_flag = true;
            i += 1;
            continue;
        }
        if arg == "-V" || arg == "--version" {
            version_flag = true;
            i += 1;
            continue;
        }
        if arg == "-m" || arg == "--pipe-msg-in" {
            if i + 1 >= args.len() {
                eprint!("error: usage: xplr {} FORMAT [ARGUMENT]...\n", arg);
                std::process::exit(1);
            }
            let format = args[i+1].clone();
            let placeholder_args: Vec<String> = args[i+2..].to_vec();
            match format_template(&format, &placeholder_args) {
                Ok(formatted) => match parse_message(&formatted) {
                    Ok(json_str) => {
                        let pipe_path = env::var("XPLR_PIPE_MSG_IN").unwrap_or_default();
                        if pipe_path.is_empty() {
                            println!("{}", json_str);
                            std::process::exit(0);
                        } else {
                            let path = Path::new(&pipe_path);
                            if !path.exists() {
                                eprint!("error: No such file or directory (os error 2)\n");
                                std::process::exit(1);
                            }
                            let content = match fs::read(path) {
                                Ok(c) => c,
                                Err(e) => {
                                    eprint!("error: {}\n", e);
                                    std::process::exit(1);
                                }
                            };
                            if content.is_empty() {
                                eprint!("error: failed to detect delimmiter\n");
                                std::process::exit(1);
                            }
                            let delim = content[0];
                            let mut file_content = content;
                            file_content.extend_from_slice(json_str.as_bytes());
                            file_content.push(delim);
                            if let Err(e) = fs::write(path, file_content) {
                                eprint!("error: {}\n", e);
                                std::process::exit(1);
                            }
                            std::process::exit(0);
                        }
                    }
                    Err(e) => {
                        eprint!("{}", e);
                        std::process::exit(1);
                    }
                },
                Err(e) => {
                    eprint!("{}", e);
                    std::process::exit(1);
                }
            }
        }
        if arg == "-M" || arg == "--print-msg-in" {
            if i + 1 >= args.len() {
                eprint!("error: usage: xplr {} FORMAT [ARGUMENT]...\n", arg);
                std::process::exit(1);
            }
            let format = args[i+1].clone();
            let placeholder_args: Vec<String> = args[i+2..].to_vec();
            match format_template(&format, &placeholder_args) {
                Ok(formatted) => match parse_message(&formatted) {
                    Ok(json_str) => {
                        print!("{}", json_str);
                        std::process::exit(0);
                    }
                    Err(e) => {
                        eprint!("{}", e);
                        std::process::exit(1);
                    }
                },
                Err(e) => {
                    eprint!("{}", e);
                    std::process::exit(1);
                }
            }
        }
        if arg == "-c" || arg == "--config" {
            if i + 1 >= args.len() {
                let name = if arg == "-c" { "-c" } else { "--config" };
                eprint!("error: usage: xplr {} PATH\n", name);
                std::process::exit(1);
            }
            let val = args[i+1].clone();
            if !Path::new(&val).exists() {
                eprint!("error: path doesn't exist: {}\n", val);
                std::process::exit(1);
            }
            i += 2;
            continue;
        }
        if arg == "--vroot" {
            if i + 1 >= args.len() {
                eprint!("error: usage: xplr --vroot PATH\n");
                std::process::exit(1);
            }
            let val = args[i+1].clone();
            if !Path::new(&val).exists() {
                eprint!("error: path doesn't exist: {}\n", val);
                std::process::exit(1);
            }
            i += 2;
            continue;
        }
        if arg == "-C" || arg == "--extra-config" {
            i += 1;
            while i < args.len() {
                let next = &args[i];
                if next == "--" { break; }
                if next.starts_with('-') { break; }
                if !Path::new(next).exists() {
                    eprint!("error: path doesn't exist: {}\n", next);
                    std::process::exit(1);
                }
                i += 1;
            }
            continue;
        }
        if arg == "--on-load" {
            i += 1;
            while i < args.len() {
                let next = &args[i];
                if next == "--" { break; }
                if next.starts_with('-') { break; }
                if let Err(e) = parse_message_for_on_load(next) {
                    eprint!("{}", e);
                    std::process::exit(1);
                }
                i += 1;
            }
            continue;
        }
        if arg == "--force-focus" || arg == "--print-pwd-as-result" || arg == "--read-only" || arg == "--read0" || arg == "--write0" || arg == "-0" || arg == "--null" {
            i += 1;
            continue;
        }
        if arg.starts_with('-') {
            eprint!("error: invalid argument: \"{}\", try `-- \"{}\"` or `--help`\n", arg, arg);
            std::process::exit(1);
        }
        positional_paths.push(arg.clone());
        i += 1;
    }

    for p in &positional_paths {
        if !Path::new(p).exists() {
            eprint!("error: path doesn't exist: {}\n", p);
            std::process::exit(1);
        }
    }

    if help_flag {
        print!("{}", HELP_TEXT);
        std::process::exit(0);
    }
    if version_flag {
        print!("{}", VERSION_TEXT);
        std::process::exit(0);
    }

    eprint!("error: No such device or address (os error 6)\n");
    std::process::exit(1);
}
