                // -M FocusByIndex abc gave "error: invalid type: string "abc", expected usize at line 1 column 21" (no variant prefix)
                // --on-load FocusByIndex abc gave "error: FocusByIndex: invalid type: string "abc", expected usize at line 1 column 15" (with variant prefix)

