fn format_template(template: &str, args: &[String]) -> Result<String, String> {
    let mut result = String::new();
    let mut arg_idx = 0;
    let chars: Vec<char> = template.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        if chars[i] == '%' {
            if i + 1 >= chars.len() {
                return Err(format!("error: xplr -m: template ended with incomplete placeholder\n"));
            }
            let next = chars[i + 1];
            match next {
                '%' => {
                    result.push('%');
                    i += 2;
                }
                's' => {
                    if arg_idx >= args.len() {
                        let col = template[..i].chars().count() + 1;
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col));
                    }
                    result.push_str(&args[arg_idx]);
                    arg_idx += 1;
                    i += 2;
                }
                'q' => {
                    if arg_idx >= args.len() {
                        let col = template[..i].chars().count() + 1;
                        return Err(format!("error: xplr -m: placeholder missing value at column {}\n", col));
                    }
                    let quoted = serde_json::to_string(&args[arg_idx]).unwrap_or_else(|_| "\"\"".to_string());
                    result.push_str(&quoted);
                    arg_idx += 1;
                    i += 2;
                }
                _ => {
                    let col = template[..i].chars().count() + 1;
                    let ph = format!("%{}", next);
                    return Err(format!("error: xplr -m: invalid placeholder '{}' at column {}, use one of '%s' or '%q', or escape it using '%%'\n", ph, col));
                }
            }
        } else {
            result.push(chars[i]);
            i += 1;
        }
    }
    if arg_idx < args.len() {
        return Err(format!("error: xplr -m: too many positional values, not enough positional placeholders\n"));
    }
    Ok(result)
}

fn parse_message(yaml_str: &str) -> Result<String, String> {
    let yaml_value: Result<serde_yaml::Value, _> = serde_yaml::from_str(yaml_str);
    let yaml_value = match yaml_value {
        Ok(v) => v,
        Err(e) => {
            return Err(format!("error: xplr -m: yaml: {}\n", e));
        }
    };
    let json_value = serde_json::to_value(&yaml_value).unwrap();
    let json_str_intermediate = serde_json::to_string(&json_value).unwrap();
    let msg_res: Result<Message, _> = serde_json::from_str(&json_str_intermediate);
    match msg_res {
        Ok(msg) => {
            Ok(serde_json::to_string(&msg).unwrap())
        },
        Err(e) => Err(format!("error: {}\n", e)),
    }
}

fn parse_message_for_on_load(yaml_str: &str) -> Result<(), String> {
    let yaml_value: Result<serde_yaml::Value, _> = serde_yaml::from_str(yaml_str);
    let yaml_value = match yaml_value {
        Ok(v) => v,
        Err(e) => return Err(format!("error: {}\n", e)),
    };

    let known_unit = [
        "ExplorePwd","ExplorePwdAsync","ExploreParentsAsync","TryCompletePath","ClearScreen","Refresh","FocusNext","FocusNextSelection","FocusNextByRelativeIndexFromInput","FocusPrevious","FocusPreviousSelection","FocusPreviousByRelativeIndexFromInput","FocusFirst","FocusLast","FocusPathFromInput","FocusByIndexFromInput","ScrollUp","ScrollDown","ScrollUpHalf","ScrollDownHalf","Enter","Back","LastVisitedPath","NextVisitedPath","PreviousVisitedDeepBranch","NextVisitedDeepBranch","FollowSymlink","UnsetVroot","ToggleVroot","ResetVroot","UpdateInputBufferFromKey","BufferInputFromKey","RemoveInputBufferLastCharacter","RemoveInputBufferLastWord","ResetInputBuffer","PopMode","PopModeKeepingInputBuffer","Select","SelectAll","UnSelect","UnSelectAll","ToggleSelection","ToggleSelectAll","ClearSelection","RemoveLastNodeFilter","ResetNodeFilters","ClearNodeFilters","ReverseNodeSorters","RemoveLastNodeSorter","ResetNodeSorters","ClearNodeSorters","SearchFromInput","SearchFuzzyFromInput","SearchFuzzyUnorderedFromInput","SearchRegexFromInput","SearchRegexUnorderedFromInput","ToggleSearchAlgorithm","EnableSearchOrder","DisableSearchOrder","ToggleSearchOrder","AcceptSearch","CancelSearch","EnableMouse","DisableMouse","ToggleMouse","StopFifo","Quit","PrintPwdAndQuit","PrintFocusPathAndQuit","PrintSelectionAndQuit","PrintResultAndQuit","PrintAppStateAndQuit","Terminate",
    ];
    let known_string = [
        "FocusPath","FocusByFileName","ChangeDirectory","SetVroot","SetInputPrompt","BufferInput","SetInputBuffer","SwitchMode","SwitchModeKeepingInputBuffer","SwitchModeBuiltin","SwitchModeBuiltinKeepingInputBuffer","SwitchModeCustom","SwitchModeCustomKeepingInputBuffer","SwitchLayout","SwitchLayoutBuiltin","SwitchLayoutCustom","BashExec","BashExec0","BashExecSilently","BashExecSilently0","CallLua","CallLuaSilently","LuaEval","LuaEvalSilently","SelectPath","UnSelectPath","ToggleSelectionByPath","Search","SearchFuzzy","SearchFuzzyUnordered","SearchRegex","SearchRegexUnordered","StartFifo","ToggleFifo","LogInfo","LogSuccess","LogWarning","LogError","Debug",
    ];
    let known_usize = [
        "FocusNextByRelativeIndex","FocusPreviousByRelativeIndex","FocusByIndex",
    ];

    match &yaml_value {
        serde_yaml::Value::String(s) => {
            if known_unit.contains(&s.as_str()) {
                return Ok(());
            }
            if known_string.contains(&s.as_str()) || known_usize.contains(&s.as_str()) {
                let res: Result<Message, _> = serde_yaml::from_str(yaml_str);
                match res {
                    Ok(_) => return Ok(()),
                    Err(e) => return Err(format!("error: {}\n", e)),
                }
            }
            let json_value = serde_json::to_value(&yaml_value).unwrap();
            let json_str = serde_json::to_string(&json_value).unwrap();
            let res: Result<Message, _> = serde_json::from_str(&json_str);
            match res {
                Ok(_) => Ok(()),
                Err(e) => {
                    let mut es = e.to_string();
                    if let Some(idx) = es.find(" at line") {
                        es = es[..idx].to_string();
                    }
                    return Err(format!("error: {}\n", es));
                }
            }
        }
        serde_yaml::Value::Mapping(m) => {
            if m.len() != 1 {
                let json_value = serde_json::to_value(&yaml_value).unwrap();
                let json_str = serde_json::to_string(&json_value).unwrap();
                let res: Result<Message, _> = serde_json::from_str(&json_str);
                match res {
                    Ok(_) => return Ok(()),
                    Err(e) => {
                        let es = e.to_string();
                        if es.contains("expected a string") {
                            return Ok(());
                        }
                        let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                        match yres {
                            Ok(_) => return Ok(()),
                            Err(ye) => return Err(format!("error: {}\n", ye)),
                        }
                    }
                }
            }
            let (k, v) = m.iter().next().unwrap();
            let key_str = match k {
                serde_yaml::Value::String(s) => s.as_str(),
                _ => {
                    let json_value = serde_json::to_value(&yaml_value).unwrap();
                    let json_str = serde_json::to_string(&json_value).unwrap();
                    let res: Result<Message, _> = serde_json::from_str(&json_str);
                    return match res {
                        Ok(_) => Ok(()),
                        Err(e) => Err(format!("error: {}\n", e)),
                    }
                }
            };

            if known_unit.contains(&key_str) {
                return Err(format!("error: invalid type: map, expected unit variant\n"));
            }
            if known_string.contains(&key_str) {
                match v {
                    serde_yaml::Value::String(_) | serde_yaml::Value::Number(_) | serde_yaml::Value::Bool(_) | serde_yaml::Value::Null => return Ok(()),
                    _ => {
                        let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                        return match yres {
                            Ok(_) => Ok(()),
                            Err(e) => Err(format!("error: {}\n", e)),
                        }
                    }
                }
            }
            if known_usize.contains(&key_str) {
                match v {
                    serde_yaml::Value::Number(n) => {
                        if n.is_u64() || n.is_i64() {
                            return Ok(());
                        } else {
                            let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
                            return match yres {
                                Ok(_) => Ok(()),
                                Err(e) => Err(format!("error: {}\n", e)),
                            }
                        }
                    }
                    _ => {
                        #[derive(Debug, Deserialize)]
                        struct Tmp {
                            FocusNextByRelativeIndex: Option<usize>,
                            FocusPreviousByRelativeIndex: Option<usize>,
                            FocusByIndex: Option<usize>,
                        }
                        let res: Result<Tmp, _> = serde_yaml::from_str(yaml_str);
                        match res {
                            Ok(_) => return Ok(()),
                            Err(e) => return Err(format!("error: {}\n", e)),
                        }
                    }
                }
            }
            let yres: Result<Message, _> = serde_yaml::from_str(yaml_str);
            match yres {
                Ok(_) => Ok(()),
                Err(e) => Err(format!("error: {}\n", e)),
            }
        }
        _ => {
            let json_value = serde_json::to_value(&yaml_value).unwrap();
            let json_str = serde_json::to_string(&json_value).unwrap();
            let res: Result<Message, _> = serde_json::from_str(&json_str);
            match res {
                Ok(_) => Ok(()),
                Err(e) => Err(format!("error: {}\n", e)),
            }
        }
    }
}

fn main() {
    let args: Vec<String> = env::args().collect();
    let mut i = 1;
    let mut help_flag = false;
    let mut version_flag = false;
    let mut positional_paths: Vec<String> = Vec::new();
    let mut ended = false;

    while i < args.len() {
        let arg = &args[i];
        if ended {
            positional_paths.push(arg.clone());
            i += 1;
            continue;
        }
        if arg == "--" {
            ended = true;
            i += 1;
            continue;
        }
        if arg == "-" {
            i += 1;
            continue;
        }
        if arg == "-h" || arg == "--help" {
            help_flag = true;
            i += 1;
            continue;
        }
        if arg == "-V" || arg == "--version" {
            version_flag = true;
            i += 1;
            continue;
        }
        if arg == "-m" || arg == "--pipe-msg-in" {
            if i + 1 >= args.len() {
                eprint!("error: usage: xplr {} FORMAT [ARGUMENT]...\n", arg);
                std::process::exit(1);
            }
            let format = args[i+1].clone();
            let placeholder_args: Vec<String> = args[i+2..].to_vec();
            match format_template(&format, &placeholder_args) {
                Ok(formatted) => match parse_message(&formatted) {
                    Ok(json_str) => {
                        let pipe_path = env::var("XPLR_PIPE_MSG_IN").unwrap_or_default();
                        if pipe_path.is_empty() {
                            println!("{}", json_str);
                            std::process::exit(0);
                        } else {
                            let path = Path::new(&pipe_path);
                            if !path.exists() {
                                eprint!("error: No such file or directory (os error 2)\n");
                                std::process::exit(1);
                            }
                            let content = match fs::read(path) {
                                Ok(c) => c,
                                Err(e) => {
                                    eprint!("error: {}\n", e);
                                    std::process::exit(1);
                                }
                            };
                            if content.is_empty() {
                                eprint!("error: failed to detect delimmiter\n");
                                std::process::exit(1);
                            }
                            let delim = content[0];
                            let mut file_content = content;
                            file_content.extend_from_slice(json_str.as_bytes());
                            file_content.push(delim);
                            if let Err(e) = fs::write(path, file_content) {
                                eprint!("error: {}\n", e);
                                std::process::exit(1);
                            }
                            std::process::exit(0);
                        }
                    }
                    Err(e) => {
                        eprint!("{}", e);
                        std::process::exit(1);
                    }
                },
                Err(e) => {
                    eprint!("{}", e);
                    std::process::exit(1);
                }
            }
        }
        if arg == "-M" || arg == "--print-msg-in" {
            if i + 1 >= args.len() {
                eprint!("error: usage: xplr {} FORMAT [ARGUMENT]...\n", arg);
                std::process::exit(1);
            }
            let format = args[i+1].clone();
            let placeholder_args: Vec<String> = args[i+2..].to_vec();
            match format_template(&format, &placeholder_args) {
                Ok(formatted) => match parse_message(&formatted) {
                    Ok(json_str) => {
                        print!("{}", json_str);
                        std::process::exit(0);
                    }
                    Err(e) => {
                        eprint!("{}", e);
                        std::process::exit(1);
                    }
                },
                Err(e) => {
                    eprint!("{}", e);
                    std::process::exit(1);
                }
            }
        }
        if arg == "-c" || arg == "--config" {
            if i + 1 >= args.len() {
                let name = if arg == "-c" { "-c" } else { "--config" };
                eprint!("error: usage: xplr {} PATH\n", name);
                std::process::exit(1);
            }
            let val = args[i+1].clone();
            if !Path::new(&val).exists() {
                eprint!("error: path doesn't exist: {}\n", val);
                std::process::exit(1);
            }
            i += 2;
            continue;
        }
        if arg == "--vroot" {
            if i + 1 >= args.len() {
                eprint!("error: usage: xplr --vroot PATH\n");
                std::process::exit(1);
            }
            let val = args[i+1].clone();
            if !Path::new(&val).exists() {
                eprint!("error: path doesn't exist: {}\n", val);
                std::process::exit(1);
            }
            i += 2;
            continue;
        }
        if arg == "-C" || arg == "--extra-config" {
            i += 1;
            while i < args.len() {
                let next = &args[i];
                if next == "--" { break; }
                if next.starts_with('-') { break; }
                if !Path::new(next).exists() {
                    eprint!("error: path doesn't exist: {}\n", next);
                    std::process::exit(1);
                }
                i += 1;
            }
            continue;
        }
        if arg == "--on-load" {
            i += 1;
            while i < args.len() {
                let next = &args[i];
                if next == "--" { break; }
                if next.starts_with('-') { break; }
                if let Err(e) = parse_message_for_on_load(next) {
                    eprint!("{}", e);
                    std::process::exit(1);
                }
                i += 1;
            }
            continue;
        }
        if arg == "--force-focus" || arg == "--print-pwd-as-result" || arg == "--read-only" || arg == "--read0" || arg == "--write0" || arg == "-0" || arg == "--null" {
            i += 1;
            continue;
        }
        if arg.starts_with('-') {
            eprint!("error: invalid argument: \"{}\", try `-- \"{}\"` or `--help`\n", arg, arg);
            std::process::exit(1);
        }
        positional_paths.push(arg.clone());
        i += 1;
    }

    for p in &positional_paths {
        if !Path::new(p).exists() {
            eprint!("error: path doesn't exist: {}\n", p);
            std::process::exit(1);
        }
    }

    if help_flag {
        print!("{}", HELP_TEXT);
        std::process::exit(0);
    }
    if version_flag {
        print!("{}", VERSION_TEXT);
        std::process::exit(0);
    }

    eprint!("error: No such device or address (os error 6)\n");
    std::process::exit(1);
}
RS
